const ToolKindThink ToolKind = "think"

type UnstructuredCommandInput struct {
	Meta  Optional[json.RawMessage]  `json:"_meta"`
	Hint  string                     `json:"hint"`
	Extra map[string]json.RawMessage `json:"-"`
}

func (v UnstructuredCommandInput) MarshalJSON() ([]byte, error) {
	return marshalObject("UnstructuredCommandInput", v)
}
func (v *UnstructuredCommandInput) UnmarshalJSON(b []byte) error {
	type plain UnstructuredCommandInput
	var p plain
	if err := unmarshalObject("UnstructuredCommandInput", b, &p); err != nil {
		return err
	}
	*v = UnstructuredCommandInput(p)
	return nil
}

type UsageUpdate struct {
	Meta  Optional[json.RawMessage]  `json:"_meta"`
	Cost  Optional[Cost]             `json:"cost"`
	Size  uint64                     `json:"size"`
	Used  uint64                     `json:"used"`
	Extra map[string]json.RawMessage `json:"-"`
}

func (v UsageUpdate) MarshalJSON() ([]byte, error) { return marshalObject("UsageUpdate", v) }
func (v *UsageUpdate) UnmarshalJSON(b []byte) error {
	type plain UsageUpdate
	var p plain
	if err := unmarshalObject("UsageUpdate", b, &p); err != nil {
		return err
	}
	*v = UsageUpdate(p)
	return nil
}

